import {unzipSync} from './vendor/fflate.js';
import {Decompress} from './vendor/fzstd.js';
// sql.js is a UMD asset: execute it in a classic worker, not in this module.
function parseDelimited(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&(quoted||field==='')){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c==='\t'&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim())&&!row[0].startsWith('#'))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw new Error('Unclosed quote in text export.');row.push(field);if(row.some(x=>x.trim())&&!row[0].startsWith('#'))rows.push(row);if(rows.length>10000)throw new Error('Maximum 10,000 notes per import.');return rows.map((fields,i)=>({id:String(i),fields}));}
export {parseDelimited};
if(typeof self!=='undefined'&&typeof WorkerGlobalScope!=='undefined'&&self instanceof WorkerGlobalScope)self.onmessage=async e=>{try{const {buffer,name}=e.data;const bytes=new Uint8Array(buffer);if(!name.toLowerCase().endsWith('.apkg')){const notes=parseDelimited(new TextDecoder().decode(bytes));self.postMessage({notes});return;}
const allowed=['collection.anki21b','collection.anki21','collection.anki2'];const files=unzipSync(bytes,{filter:f=>{if(!allowed.includes(f.name))return false;if(f.originalSize>50*1024*1024)throw new Error('Deck database exceeds 50 MB.');return true;}});const chosen=allowed.find(n=>files[n]);if(!chosen)throw new Error('No Anki collection database was found.');let data=files[chosen];if(chosen.endsWith('21b')){const chunks=[];let size=0;const decoder=new Decompress(chunk=>{size+=chunk.length;if(size>50*1024*1024)throw new Error('Expanded deck exceeds 50 MB.');chunks.push(chunk);});decoder.push(data,true);data=new Uint8Array(size);let offset=0;for(const c of chunks){data.set(c,offset);offset+=c.length;}}
const sqlWorker=new Worker(new URL('./sqlite-worker.js',import.meta.url));const result=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{sqlWorker.terminate();reject(new Error('Deck database parsing timed out.'));},20000);sqlWorker.onmessage=e=>{clearTimeout(timer);sqlWorker.terminate();e.data.error?reject(new Error(e.data.error)):resolve(e.data);};sqlWorker.onerror=()=>{clearTimeout(timer);sqlWorker.terminate();reject(new Error('Unable to read the deck database.'));};sqlWorker.postMessage(data.buffer,[data.buffer]);});self.postMessage(result);
}catch(err){self.postMessage({error:err.message||'Unable to import this Anki deck.'});}};
